<?php
declare(strict_types=1);
namespace KodVadAll\Modules\Production;
use PDO;
use RuntimeException;
use Throwable;
use KodVadAll\Core\NotificationService;
final class ProductionController
{
 public static function handle(PDO $db,array $admin):void
 {
  kd_require_permission('production.view');$errors=[];$success='';
  if($_SERVER['REQUEST_METHOD']==='POST'){kd_csrf_check();kd_require_permission('production.manage');$action=(string)($_POST['form_action']??'');try{
   if($action==='recipe'){$name=trim((string)($_POST['name']??''));$output=(int)($_POST['output_product_id']??0);$batch=(float)($_POST['batch_size']??1);$components=is_array($_POST['component_product_id']??null)?$_POST['component_product_id']:[];$quantities=is_array($_POST['quantity_per_batch']??null)?$_POST['quantity_per_batch']:[];if($name===''||$output<1||$batch<=0)throw new RuntimeException('Reçete adı, çıktı ürünü ve parti miktarı gereklidir.');$items=[];foreach($components as $i=>$component){$pid=(int)$component;$qty=(float)($quantities[$i]??0);if($pid>0&&$qty>0){if($pid===$output)throw new RuntimeException('Üretilen ürün kendi hammaddesi olamaz.');$items[$pid]=$qty;}}if(!$items)throw new RuntimeException('En az bir hammadde ekleyin.');$db->beginTransaction();$db->prepare('INSERT INTO production_recipes (name,output_product_id,batch_size,status,notes,created_by,created_at) VALUES (?,?,?,\\'active\\',?,?,NOW())')->execute([$name,$output,$batch,trim((string)($_POST['notes']??''))?:null,(int)$admin['id']]);$recipeId=(int)$db->lastInsertId();$ins=$db->prepare('INSERT INTO production_recipe_items (recipe_id,component_product_id,quantity_per_batch,created_at) VALUES (?,?,?,NOW())');foreach($items as $pid=>$qty)$ins->execute([$recipeId,$pid,$qty]);$db->commit();kd_audit('production.recipe_created','production_recipe',$recipeId);$success='Üretim reçetesi oluşturuldu.';}
   if($action==='order'){$recipe=(int)($_POST['recipe_id']??0);$qty=(float)($_POST['output_quantity']??0);if($recipe<1||$qty<=0)throw new RuntimeException('Reçete ve üretim miktarı seçin.');$db->prepare("INSERT INTO production_orders (order_number,recipe_id,output_quantity,status,planned_at,created_by,notes,created_at) VALUES (?,?,?,'planned',?,?,?,NOW())")->execute(['TMP-PROD-'.bin2hex(random_bytes(4)),$recipe,$qty,trim((string)($_POST['planned_at']??''))?:null,(int)$admin['id'],trim((string)($_POST['notes']??''))?:null]);$id=(int)$db->lastInsertId();$number='PRD-'.date('Y').'-'.str_pad((string)$id,6,'0',STR_PAD_LEFT);$db->prepare('UPDATE production_orders SET order_number=? WHERE id=?')->execute([$number,$id]);$success='Üretim emri oluşturuldu.';}
   if($action==='complete'){$orderId=(int)($_POST['order_id']??0);$db->beginTransaction();$q=$db->prepare("SELECT po.*,r.output_product_id,r.batch_size,r.name recipe_name FROM production_orders po JOIN production_recipes r ON r.id=po.recipe_id WHERE po.id=? FOR UPDATE");$q->execute([$orderId]);$order=$q->fetch();if(!$order||$order['status']!=='planned')throw new RuntimeException('Tamamlanabilir üretim emri bulunamadı.');$q=$db->prepare('SELECT ri.*,p.name,p.stock_quantity,p.track_stock FROM production_recipe_items ri JOIN products p ON p.id=ri.component_product_id WHERE ri.recipe_id=? FOR UPDATE');$q->execute([(int)$order['recipe_id']]);$components=$q->fetchAll();$materials=[];foreach($components as $c){$required=(float)$c['quantity_per_batch']*(float)$order['output_quantity']/(float)$order['batch_size'];if((int)$c['track_stock']&&(float)$c['stock_quantity']<$required)throw new RuntimeException('Yetersiz hammadde: '.$c['name']);$materials[]=[$c,$required];}
    $q=$db->prepare('SELECT * FROM products WHERE id=? FOR UPDATE');$q->execute([(int)$order['output_product_id']]);$output=$q->fetch();if(!$output)throw new RuntimeException('Üretim çıktı ürünü bulunamadı.');foreach($materials as [$c,$required]){if((int)$c['track_stock']){$before=(float)$c['stock_quantity'];$after=$before-$required;$db->prepare('UPDATE products SET stock_quantity=?,updated_at=NOW() WHERE id=?')->execute([$after,(int)$c['component_product_id']]);$db->prepare("INSERT INTO product_stock_movements (product_id,user_id,movement_type,quantity,before_quantity,after_quantity,note,reference_type,reference_id,created_at) VALUES (?,?,'out',?,?,?,?, 'production',?,NOW())")->execute([(int)$c['component_product_id'],(int)$admin['id'],$required,$before,$after,'Üretim '.$order['order_number'],$orderId]);}$db->prepare('INSERT INTO production_order_materials (production_order_id,product_id,product_name,quantity_required,quantity_consumed,created_at) VALUES (?,?,?,?,?,NOW())')->execute([$orderId,(int)$c['component_product_id'],$c['name'],$required,$required]);}
    if((int)$output['track_stock']){$before=(float)$output['stock_quantity'];$after=$before+(float)$order['output_quantity'];$db->prepare('UPDATE products SET stock_quantity=?,updated_at=NOW() WHERE id=?')->execute([$after,(int)$output['id']]);$db->prepare("INSERT INTO product_stock_movements (product_id,user_id,movement_type,quantity,before_quantity,after_quantity,note,reference_type,reference_id,created_at) VALUES (?,?,'in',?,?,?,?, 'production',?,NOW())")->execute([(int)$output['id'],(int)$admin['id'],(float)$order['output_quantity'],$before,$after,'Üretim '.$order['order_number'],$orderId]);}
    $db->prepare("UPDATE production_orders SET status='completed',started_at=COALESCE(started_at,NOW()),completed_at=NOW() WHERE id=?")->execute([$orderId]);$db->commit();kd_audit('production.completed','production_order',$orderId);NotificationService::notifyRoles($db,['owner','admin','manager'],'Üretim tamamlandı',$order['order_number'].' üretim emri tamamlandı.','index.php?page=production','success');$success='Üretim tamamlandı, stoklar güncellendi.';}
  }catch(Throwable $e){if($db->inTransaction())$db->rollBack();$errors[]=$e instanceof RuntimeException?$e->getMessage():'Üretim işlemi tamamlanamadı.';}}
  $products=$db->query("SELECT id,name,sku,stock_quantity FROM products WHERE status='active' ORDER BY name")->fetchAll();$recipes=$db->query("SELECT r.*,p.name output_name FROM production_recipes r JOIN products p ON p.id=r.output_product_id WHERE r.status='active' ORDER BY r.id DESC")->fetchAll();$orders=$db->query("SELECT po.*,r.name recipe_name,p.name output_name FROM production_orders po JOIN production_recipes r ON r.id=po.recipe_id JOIN products p ON p.id=r.output_product_id ORDER BY po.id DESC LIMIT 100")->fetchAll();$pageTitle='Üretim & Reçete Yönetimi';ob_start();require KD_ROOT.'/app/Views/production/index.php';$content=ob_get_clean();require KD_ROOT.'/app/Views/layouts/admin.php';
 }
}
